'{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "data": {
    "name": "dataset"
  },
  "width": 247.0,
  "height": 120,
  "transform": [
    {
      "joinaggregate": [
        {
          "op": "min",
          "field": "Baseline No-show Rate",
          "as": "lo"
        },
        {
          "op": "max",
          "field": "Baseline No-show Rate",
          "as": "hi"
        }
      ]
    },
    {
      "calculate": "(datum[''Baseline No-show Rate''] - datum.lo) / max(datum.hi - datum.lo, 1e-9)",
      "as": "t"
    },
    {
      "calculate": "format(datum[''Baseline No-show Rate''], ''.1%'')",
      "as": "vtxt"
    }
  ],
  "layer": [
    {
      "mark": {
        "type": "rect",
        "cornerRadius": 6
      },
      "encoding": {
        "x": {
          "field": "Time of Day",
          "type": "ordinal",
          "sort": [
            "Early AM",
            "Late AM",
            "Afternoon",
            "Evening"
          ],
          "title": null,
          "scale": {
            "domain": [
              "Early AM",
              "Late AM",
              "Afternoon",
              "Evening"
            ],
            "paddingInner": 0.06
          },
          "axis": {
            "orient": "top",
            "labelAngle": 0,
            "labelColor": "#667085",
            "labelFontSize": 10
          }
        },
        "y": {
          "field": "Patient Area",
          "type": "ordinal",
          "sort": [
            "Semi-urban",
            "Urban"
          ],
          "title": null,
          "scale": {
            "domain": [
              "Semi-urban",
              "Urban"
            ],
            "paddingInner": 0.1
          },
          "axis": {
            "labelColor": "#344054",
            "labelFontSize": 10.5
          }
        },
        "color": {
          "field": "Baseline No-show Rate",
          "type": "quantitative",
          "legend": null,
          "scale": {
            "range": [
              "#FFF1EA",
              "#C24E20"
            ]
          }
        },
        "tooltip": [
          {
            "field": "Patient Area"
          },
          {
            "field": "Time of Day"
          },
          {
            "field": "Baseline No-show Rate",
            "format": ".1%"
          },
          {
            "field": "Baseline Eligible Appointments",
            "format": ","
          }
        ]
      }
    },
    {
      "mark": {
        "type": "text",
        "fontSize": 11,
        "fontWeight": 600,
        "dy": -6
      },
      "encoding": {
        "x": {
          "field": "Time of Day",
          "type": "ordinal",
          "sort": [
            "Early AM",
            "Late AM",
            "Afternoon",
            "Evening"
          ],
          "title": null,
          "scale": {
            "domain": [
              "Early AM",
              "Late AM",
              "Afternoon",
              "Evening"
            ],
            "paddingInner": 0.06
          },
          "axis": {
            "orient": "top",
            "labelAngle": 0,
            "labelColor": "#667085",
            "labelFontSize": 10
          }
        },
        "y": {
          "field": "Patient Area",
          "type": "ordinal",
          "sort": [
            "Semi-urban",
            "Urban"
          ],
          "title": null,
          "scale": {
            "domain": [
              "Semi-urban",
              "Urban"
            ],
            "paddingInner": 0.1
          },
          "axis": {
            "labelColor": "#344054",
            "labelFontSize": 10.5
          }
        },
        "text": {
          "field": "vtxt"
        },
        "color": {
          "condition": {
            "test": "datum.t >= 0.45",
            "value": "#FFFFFF"
          },
          "value": "#101828"
        }
      }
    },
    {
      "transform": [
        {
          "calculate": "''n='' + format(datum[''Baseline Eligible Appointments''], '','')",
          "as": "ntxt"
        }
      ],
      "mark": {
        "type": "text",
        "fontSize": 9,
        "dy": 9,
        "opacity": 0.85
      },
      "encoding": {
        "x": {
          "field": "Time of Day",
          "type": "ordinal",
          "sort": [
            "Early AM",
            "Late AM",
            "Afternoon",
            "Evening"
          ],
          "title": null,
          "scale": {
            "domain": [
              "Early AM",
              "Late AM",
              "Afternoon",
              "Evening"
            ],
            "paddingInner": 0.06
          },
          "axis": {
            "orient": "top",
            "labelAngle": 0,
            "labelColor": "#667085",
            "labelFontSize": 10
          }
        },
        "y": {
          "field": "Patient Area",
          "type": "ordinal",
          "sort": [
            "Semi-urban",
            "Urban"
          ],
          "title": null,
          "scale": {
            "domain": [
              "Semi-urban",
              "Urban"
            ],
            "paddingInner": 0.1
          },
          "axis": {
            "labelColor": "#344054",
            "labelFontSize": 10.5
          }
        },
        "text": {
          "field": "ntxt"
        },
        "color": {
          "condition": {
            "test": "datum.t >= 0.45",
            "value": "#FFFFFF"
          },
          "value": "#344054"
        }
      }
    }
  ],
  "autosize": {
    "type": "pad"
  }
}'

'{
  "background": null,
  "font": "Segoe UI",
  "view": {
    "stroke": null
  },
  "padding": 2,
  "axis": {
    "labelFont": "Segoe UI",
    "labelFontSize": 10,
    "labelColor": "#667085",
    "titleFont": "Segoe UI",
    "titleFontSize": 10,
    "titleColor": "#667085",
    "titleFontWeight": "normal",
    "domain": false,
    "ticks": false,
    "gridColor": "#EEF0F4",
    "labelPadding": 6
  },
  "legend": {
    "labelFont": "Segoe UI",
    "labelFontSize": 10.5,
    "labelColor": "#344054",
    "symbolType": "circle",
    "symbolSize": 70,
    "title": null,
    "orient": "top",
    "direction": "horizontal",
    "columnPadding": 14
  },
  "text": {
    "font": "Segoe UI",
    "fontSize": 11,
    "color": "#344054"
  },
  "title": {
    "font": "Segoe UI"
  },
  "concat": {
    "spacing": 8
  }
}'
